 await dyn.getByRole('button',{name:'Nở dòng cuối',exact:true}).evaluate(e=>e.click());await dyn.waitForFunction(total=>document.querySelector('[data-virtual-viewport]').scrollHeight>total,followed.total);await dyn.waitForTimeout(100);assert((await snapDyn()).bottom<=2);console.log('History prepend, reading append, tail follow and late growth passed',JSON.stringify({reading,history,newWhileReading,followed}));
 const dh=await dv.elementHandle();await dyn.locator('#modules button').first().evaluate(e=>e.click());assert(await dh.evaluate(e=>e.dataset.virtualDisposed==='true'&&!e.isConnected));await dh.dispose();console.log('Dynamic Virtualizer anchor and edge proof',JSON.stringify({before,after,own,end}));await dyn.close();
